package dev.veltraph.client.garden.pests;

import dev.veltraph.client.config.PestAutoAdmissionConfig;
import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

final class PestAutoAdmissionTrackerTest {
    private static final PestAutoAdmissionBindings.Source TAB=PestAutoAdmissionBindings.Source.TAB,SIDE=PestAutoAdmissionBindings.Source.SIDEBAR;
    private final PestAutoAdmission.Scope scope=new PestAutoAdmission.Scope(new Object(),new Object(),new Object(),"real-profile",1);
    private final PestAutoAdmissionTracker tracker=new PestAutoAdmissionTracker();
    private static PestAutoAdmissionBindings contract(){return new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.TRACKER,1,
        new PestAutoAdmissionSignals.Bindings("native-tab: ","native-side: "),new PestAutoAdmissionBindings.Counter(TAB,"entities: "),
        new PestAutoAdmissionBindings.Counter(TAB,"plots: "),new PestAutoAdmissionBindings.Counter(SIDE,"scheduled: "),new PestAutoAdmissionBindings.Counter(SIDE,"completed: "),
        new PestAutoAdmissionBindings.Flag(TAB,"blocked: true","blocked: false"),new PestAutoAdmissionBindings.Marker(SIDE,"generation: "));}
    private List<String> tab(int total,int entities,int plots,boolean blocked){return List.of("native-tab: x"+total,"entities: "+entities,"plots: "+plots,"blocked: "+blocked);}
    private List<String> side(int target,int completed,String generation){return List.of("scheduled: "+target,"completed: "+completed,"generation: "+generation);}
    private void observe(long tick,int total,int entities,int plots,int target,int done,boolean blocked,String generation){tracker.observe(scope,tick,contract(),tab(total,entities,plots,blocked),side(target,done,generation));}
    private boolean ready(long tick,boolean leave){return tracker.snapshot(scope,tick).filter(s->PestAutoAdmission.ready(s,scope,tick,leave)).isPresent();}
    @Test void automaticAdapterHasNoDefaultOnOrFabricatedBindings(){assertFalse(PestAutoAdmissionConfig.PEST_AUTO_ADMISSION_ENABLED.defaultValue());assertEquals("",PestAutoAdmissionConfig.PEST_AUTO_ADMISSION_BINDINGS.defaultValue());}
    @Test void freshIndependentOneAndTwoWitnessesRespectRetention(){observe(1,1,0,0,1,0,false,"a");assertFalse(ready(1,true));assertTrue(ready(1,false));observe(2,2,0,0,2,0,false,"a");assertTrue(ready(2,true));}
    @Test void nativeOneParentTwoCannotStart(){observe(1,1,0,0,2,0,false,"a");assertFalse(ready(1,true));}
    @Test void nativeTwoParentOneCannotStart(){observe(1,2,0,0,1,0,false,"a");assertFalse(ready(1,true));}
    @Test void bothZeroOperandsRemainZero(){observe(1,0,0,0,0,0,false,"a");assertFalse(ready(1,false));}
    @Test void bothBlacklistedEntityAndPlotCardinalitiesAreCounted(){observe(1,3,1,1,4,0,false,"a");assertFalse(ready(1,true));assertTrue(ready(1,false));assertEquals(1,tracker.snapshot(scope,1).orElseThrow().counts().available());}
    @Test void acknowledgedCompletionChangesOnlyTheIndependentPendingDifference(){observe(1,4,0,0,4,2,false,"a");assertTrue(ready(1,true));observe(2,4,0,0,4,3,false,"a");assertFalse(ready(2,true));assertTrue(ready(2,false));assertEquals(4,tracker.snapshot(scope,2).orElseThrow().counts().available());}
    @Test void scheduledTrapCounterIncreasePreservesAcknowledgedCompletionOffset(){observe(1,4,0,0,2,1,false,"a");assertFalse(ready(1,true));observe(2,4,0,0,5,1,false,"a");assertTrue(ready(2,true));assertEquals(4,tracker.snapshot(scope,2).orElseThrow().counts().pending());}
    @Test void pendingBelowZeroNeverTurnsIntoAdmission(){observe(1,4,0,0,2,3,false,"a");assertFalse(ready(1,false));}
    @Test void everyMissingIndependentWitnessInvalidatesTheCurrentFrame(){var fullTab=tab(4,0,0,false);var fullSide=side(4,0,"a");for(int i=0;i<fullTab.size();i++){var rows=new ArrayList<>(fullTab);rows.remove(i);tracker.reset();tracker.observe(scope,1,contract(),rows,fullSide);assertFalse(ready(1,false));}for(int i=0;i<fullSide.size();i++){var rows=new ArrayList<>(fullSide);rows.remove(i);tracker.reset();tracker.observe(scope,1,contract(),fullTab,rows);assertFalse(ready(1,false));}}
    @Test void duplicateCounterOrGenerationWitnessCannotBorrowFirstRow(){for(String duplicate:List.of("scheduled: 4","completed: 0","generation: a")){var rows=new ArrayList<>(side(4,0,"a"));rows.add(duplicate);tracker.reset();tracker.observe(scope,1,contract(),tab(4,0,0,false),rows);assertTrue(tracker.snapshot(scope,1).isEmpty());}}
    @Test void duplicatedNativeCountWitnessIsUnknown(){var rows=new ArrayList<>(tab(4,0,0,false));rows.add("native-tab: x4");tracker.observe(scope,1,contract(),rows,side(4,0,"a"));assertTrue(tracker.snapshot(scope,1).isEmpty());}
    @Test void contradictoryBlockedRowsCannotAuthorize(){var rows=new ArrayList<>(tab(4,0,0,false));rows.add("blocked: true");tracker.observe(scope,1,contract(),rows,side(4,0,"a"));assertTrue(tracker.snapshot(scope,1).isEmpty());}
    @Test void blockedFlagStaysSetUntilFreshObservedGenerationReset(){observe(1,4,0,0,4,0,true,"a");assertFalse(ready(1,true));observe(2,4,0,0,4,0,false,"a");assertFalse(ready(2,true));assertTrue(tracker.snapshot(scope,2).orElseThrow().sourceBlocked());observe(3,4,0,0,4,0,false,"b");assertTrue(ready(3,true));}
    @Test void completionRegressionInvalidatesGenerationUntilObservedReset(){observe(1,4,0,0,4,2,false,"a");observe(2,4,0,0,4,1,false,"a");assertFalse(ready(2,true));observe(3,4,0,0,4,2,false,"a");assertFalse(ready(3,true));observe(4,2,0,0,2,0,false,"b");assertTrue(ready(4,true));}
    @Test void scheduledRegressionInvalidatesGenerationUntilObservedReset(){observe(1,4,0,0,4,0,false,"a");observe(2,4,0,0,3,0,false,"a");assertFalse(ready(2,true));observe(3,4,0,0,4,0,false,"a");assertFalse(ready(3,true));observe(4,2,0,0,2,0,false,"b");assertTrue(ready(4,true));}
    @Test void resetIdentityNeverInventsMissingInitialCounters(){observe(1,4,0,0,4,2,false,"a");tracker.observe(scope,2,contract(),tab(2,0,0,false),List.of("generation: b"));assertTrue(tracker.snapshot(scope,2).isEmpty());}
    @Test void oldOrFutureCurrentTickCannotReadCachedWitness(){observe(10,2,0,0,2,0,false,"a");assertFalse(ready(9,true));assertFalse(ready(11,true));assertTrue(ready(10,true));}
    @Test void sameTickContradictoryReadCannotReplaceOriginalNativeFrame(){observe(10,1,0,0,1,0,false,"a");observe(10,2,0,0,2,0,false,"a");assertFalse(ready(10,true));}
    @Test void everyActualIdentityAndProfileAndPlotMustMatch(){observe(1,2,0,0,2,0,false,"a");for(var changed:List.of(new PestAutoAdmission.Scope(new Object(),scope.world(),scope.connection(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),new Object(),scope.connection(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),scope.world(),new Object(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),scope.world(),scope.connection(),"other-profile",1),new PestAutoAdmission.Scope(scope.player(),scope.world(),scope.connection(),scope.profile(),2)))assertTrue(tracker.snapshot(changed,1).isEmpty());}
    @Test void stopResetRemovesAllCachedNativeAdmission(){observe(1,2,0,0,2,0,false,"a");tracker.reset();assertFalse(ready(1,true));assertNull(tracker.target());}
    @Test void invalidOrWrongSelectedPlotScopeCannotObserve(){tracker.observe(new PestAutoAdmission.Scope(scope.player(),scope.world(),scope.connection(),scope.profile(),2),1,contract(),tab(2,0,0,false),side(2,0,"a"));assertTrue(tracker.snapshot(scope,1).isEmpty());}
    @Test void sidebarSourceTotalUsesRecoveredGrammarWithoutParentAlias(){var rows=new ArrayList<>(side(2,0,"a"));rows.add("native-side: 2");tracker.observe(scope,1,contract(),List.of("entities: 0","plots: 0","blocked: false"),rows);assertTrue(ready(1,true));}
    @Test void signedNegativeCounterAndOverflowRemainUnknown(){for(String value:List.of("-1","2147483648","2 ")){tracker.reset();tracker.observe(scope,1,contract(),tab(2,0,0,false),List.of("scheduled: "+value,"completed: 0","generation: a"));assertFalse(ready(1,false));}}
    @Test void exactCounterSuffixAcceptsPositiveSignWithoutChangingArithmetic(){tracker.observe(scope,1,contract(),tab(2,0,0,false),List.of("scheduled: +3","completed: +1","generation: a"));assertTrue(ready(1,true));}
    @Test void nativeSeedCannotBeInferredFromDeskLore(){tracker.observe(scope,1,contract(),List.of(),List.of("Garden","Pests: 8 \ue019"));assertTrue(tracker.snapshot(scope,1).isEmpty());}
    @Test void nativeRowsCannotServeTwoDifferentCountRoles(){assertThrows(IllegalArgumentException.class,()->new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.TRACKER,1,contract().nativeTotal(),contract().excludedEntities(),contract().excludedPlots(),new PestAutoAdmissionBindings.Counter(SIDE,"native-side: "),contract().completed(),contract().sourceBlocked(),contract().batchGeneration()));}
    @Test void duplicatedWidgetInAnotherNativeViewIsStillNotIndependentCounterEvidence(){assertThrows(IllegalArgumentException.class,()->new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.TRACKER,1,contract().nativeTotal(),contract().excludedEntities(),contract().excludedPlots(),new PestAutoAdmissionBindings.Counter(TAB,"native-side: "),contract().completed(),contract().sourceBlocked(),contract().batchGeneration()));}
    @Test void prefixOverlapAndSameCounterWitnessAreRejected(){for(String alias:List.of("scheduled: ","scheduled:")){assertThrows(IllegalArgumentException.class,()->new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.TRACKER,1,contract().nativeTotal(),contract().excludedEntities(),contract().excludedPlots(),contract().scheduledTotal(),new PestAutoAdmissionBindings.Counter(SIDE,alias),contract().sourceBlocked(),contract().batchGeneration()));}}
    @Test void malformedUnsetFormattedOrMultilineBindingsAreRejected(){for(String prefix:List.of(""," ","§aValue: ","line\n"))assertThrows(IllegalArgumentException.class,()->new PestAutoAdmissionBindings.Counter(TAB,prefix));assertThrows(IllegalArgumentException.class,()->new PestAutoAdmissionBindings.Flag(TAB,"same","same"));}
    @Test void validJsonRoundTripKeepsIndependentContractAndNoSeedDefaults(){var raw=new com.google.gson.Gson().toJson(contract());assertEquals(contract(),PestAutoAdmissionBindings.read(raw));assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read("{}"));}
    @Test void unknownTopLevelAndNestedJsonFieldsCannotArmBindings(){String raw=new com.google.gson.Gson().toJson(contract());assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read(raw.substring(0,raw.length()-1)+",\"unexpected\":1}"));assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read(raw.replace("\"scheduledTotal\":{","\"scheduledTotal\":{\"unexpected\":1,")));}
    @Test void duplicateTopLevelAndNestedJsonFieldsCannotArmBindings(){String raw=new com.google.gson.Gson().toJson(contract());assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read(raw.replace("\"plot\":1","\"plot\":1,\"plot\":1")));assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read(raw.replace("\"scheduledTotal\":{","\"scheduledTotal\":{\"source\":\"SIDEBAR\",")));}
    @Test void wrongJsonTypesFractionalPlotAndTrailingValuesCannotArmBindings(){String raw=new com.google.gson.Gson().toJson(contract());for(String bad:List.of(raw.replace("\"plot\":1","\"plot\":\"1\""),raw.replace("\"plot\":1","\"plot\":1.5"),raw+"{}",raw.replace("\"target\":\"TRACKER\"","\"target\":null")))assertThrows(IllegalArgumentException.class,()->PestAutoAdmissionBindings.read(bad));}
    @Test void claimRequiresFreshActualAdmissibleTwoCountFrame(){observe(1,1,0,0,2,0,false,"a");assertTrue(tracker.claim(scope,1,true).isEmpty());observe(2,2,0,0,2,0,false,"a");assertTrue(tracker.claim(scope,1,true).isEmpty());assertTrue(tracker.claim(scope,2,true).isPresent());}
    @Test void previewDoesNotConsumeAndOpaqueClaimIsStableForItsNativeFrame(){observe(1,2,0,0,2,0,false,"a");var first=tracker.claim(scope,1,true).orElseThrow();for(int i=0;i<5;i++)assertSame(first,tracker.claim(scope,1,true).orElseThrow());assertTrue(ready(1,true));}
    @Test void missingOrUnprovenPreparedReservationDoesNotRetireObservation(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);assertNotNull(token);assertFalse(tracker.consume(claim,scope,1,token,()->false));assertFalse(tracker.consume(claim,scope,1,null,()->true));assertTrue(ready(1,true));}
    @Test void retirementCapacityNeverEvictsOldEvidenceToPermitRetry(){for(int i=0;i<256;i++){observe(i+1,2,0,0,2,0,false,"batch-"+i);var claim=tracker.claim(scope,i+1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);assertTrue(tracker.consume(claim,scope,i+1,token,()->lease.state()==dev.veltraph.client.rewarp.FarmMaintenanceLease.State.PREPARED));}tracker.reset();observe(300,2,0,0,2,0,false,"new-batch");assertFalse(ready(300,true));observe(301,2,0,0,2,0,false,"batch-0");assertFalse(ready(301,true));}
    @Test void actualPreparedReservationRetiresOnceEvenAfterCancelAndReset(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();Object farm=new Object(),helper=new Object();var token=lease.prepare(farm,helper,10,1000);assertTrue(tracker.consume(claim,scope,1,token,()->lease.state()==dev.veltraph.client.rewarp.FarmMaintenanceLease.State.PREPARED&&lease.owns(token)&&lease.farm()==farm&&lease.helper()==helper));assertFalse(tracker.consume(claim,scope,1,token,()->true));lease.cancel(token,"unknown native outcome");tracker.reset();observe(2,2,0,0,2,0,false,"a");assertFalse(ready(2,true));observe(3,2,0,0,2,0,false,"b");assertTrue(ready(3,true));}
    @Test void retiredBatchCannotReviveOnDifferentNativeIdentityProfileOrBinding(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);assertTrue(tracker.consume(claim,scope,1,token,()->lease.owns(token)&&lease.state()==dev.veltraph.client.rewarp.FarmMaintenanceLease.State.PREPARED));var changed=new PestAutoAdmission.Scope(new Object(),new Object(),new Object(),"different-profile",1);tracker.observe(changed,2,contract(),tab(2,0,0,false),side(2,0,"a"));assertTrue(tracker.snapshot(changed,2).isEmpty());var old=contract();var otherTarget=new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.CURRENT_PLOT,1,old.nativeTotal(),old.excludedEntities(),old.excludedPlots(),old.scheduledTotal(),old.completed(),old.sourceBlocked(),old.batchGeneration());tracker.observe(changed,3,otherTarget,tab(2,0,0,false),side(2,0,"a"));assertTrue(tracker.snapshot(changed,3).isEmpty());}
    @Test void staleClaimCannotConsumeNewerFrameOrForeignScope(){observe(1,2,0,0,2,0,false,"a");var old=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);observe(2,2,0,0,2,0,false,"a");assertFalse(tracker.consume(old,scope,2,token,()->true));var current=tracker.claim(scope,2,true).orElseThrow();assertFalse(tracker.consume(current,new PestAutoAdmission.Scope(new Object(),scope.world(),scope.connection(),scope.profile(),1),2,token,()->true));assertTrue(ready(2,true));}
    @Test void postCommitProofIsTooLateToConsumePreparedAdmission(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);assertTrue(lease.commit(token));assertFalse(tracker.consume(claim,scope,1,token,()->lease.state()==dev.veltraph.client.rewarp.FarmMaintenanceLease.State.PREPARED));assertTrue(ready(1,true));}
    @Test void rejectedAttemptRetiresGenerationOnceWithoutInventingPreparedReceipt(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();assertTrue(tracker.reject(claim,scope,1));assertFalse(tracker.reject(claim,scope,1));assertFalse(ready(1,true));assertTrue(tracker.status().contains("refused activation"));tracker.reset();observe(2,2,0,0,2,0,false,"a");assertFalse(ready(2,true));observe(3,2,0,0,2,0,false,"b");assertTrue(ready(3,true));}
    @Test void stalePastFutureOrNullRefusalCannotRetireCurrentObservation(){observe(1,2,0,0,2,0,false,"a");var old=tracker.claim(scope,1,true).orElseThrow();observe(2,2,0,0,2,0,false,"a");var current=tracker.claim(scope,2,true).orElseThrow();assertFalse(tracker.reject(old,scope,2));assertFalse(tracker.reject(current,scope,1));assertFalse(tracker.reject(current,scope,3));assertFalse(tracker.reject(null,scope,2));assertTrue(ready(2,true));}
    @Test void everyForeignNativeIdentityProfileAndPlotCannotRejectCurrentClaim(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();for(var changed:List.of(new PestAutoAdmission.Scope(new Object(),scope.world(),scope.connection(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),new Object(),scope.connection(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),scope.world(),new Object(),scope.profile(),1),new PestAutoAdmission.Scope(scope.player(),scope.world(),scope.connection(),"other-profile",1),new PestAutoAdmission.Scope(scope.player(),scope.world(),scope.connection(),scope.profile(),2)))assertFalse(tracker.reject(claim,changed,1));assertTrue(ready(1,true));}
    @Test void claimFromAnotherTrackerCannotRetireThisFrame(){observe(1,2,0,0,2,0,false,"a");var other=new PestAutoAdmissionTracker();other.observe(scope,1,contract(),tab(2,0,0,false),side(2,0,"a"));var foreign=other.claim(scope,1,true).orElseThrow();assertFalse(tracker.reject(foreign,scope,1));assertTrue(ready(1,true));}
    @Test void refusedPreparedConsumptionCanBeRetiredAfterExactLeaseCancellation(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var lease=new dev.veltraph.client.rewarp.FarmMaintenanceLease();var token=lease.prepare(new Object(),new Object(),10,1000);assertFalse(tracker.consume(claim,scope,1,token,()->false));lease.cancel(token,"actual reservation proof refused");assertEquals(dev.veltraph.client.rewarp.FarmMaintenanceLease.State.CANCELLED,lease.state());assertTrue(tracker.reject(claim,scope,1));assertFalse(tracker.consume(claim,scope,1,token,()->true));}
    @Test void rejectedGenerationSurvivesScopeResetAndBindingDrift(){observe(1,2,0,0,2,0,false,"a");assertTrue(tracker.reject(tracker.claim(scope,1,true).orElseThrow(),scope,1));tracker.reset();var changed=new PestAutoAdmission.Scope(new Object(),new Object(),new Object(),"changed-farm",1);var old=contract();var otherTarget=new PestAutoAdmissionBindings(PestAutoAdmissionBindings.Target.CURRENT_PLOT,1,old.nativeTotal(),old.excludedEntities(),old.excludedPlots(),old.scheduledTotal(),old.completed(),old.sourceBlocked(),old.batchGeneration());tracker.observe(changed,2,otherTarget,tab(2,0,0,false),side(2,0,"a"));assertTrue(tracker.snapshot(changed,2).isEmpty());}
    @Test void actualActivationGuardRefusalRetiresClaimWithoutEnablingHelper(){observe(1,2,0,0,2,0,false,"a");var claim=tracker.claim(scope,1,true).orElseThrow();var manager=new dev.veltraph.client.core.ModuleManager();var module=new dev.veltraph.client.core.AbstractModule("pest_refusal","Pest refusal",dev.veltraph.client.core.ModuleCategory.INTERMEDIARY){public java.util.Optional<String> preStartCheck(){return java.util.Optional.of("Exact native tool unavailable");}};manager.register(module);var guard=new dev.veltraph.client.core.ModuleActivationGuard(manager,new dev.veltraph.client.game.FixedGameContextService(new dev.veltraph.client.game.GameContext(true,true,dev.veltraph.client.game.GameArea.GARDEN)),message->{});assertFalse(guard.start(module));assertFalse(module.isEnabled());assertTrue(tracker.reject(claim,scope,1));observe(2,2,0,0,2,0,false,"a");assertFalse(ready(2,true));}
}
